:root{
  --bg:#0c0d10; --panel:#14161b; --panel-2:#191c23;
  --line:#262a33; --line-soft:#1d2129;
  --ink:#e8eaf0; --muted:#98a0b3; --dim:#707a8c;
  --yellow:#faff69; --cyan:#6fe3ff; --orange:#ff9d5c; --green:#7dffb2; --red:#ff7d7d;
  --mono:"IBM Plex Mono",ui-monospace,monospace;
  --jp:"Zen Kaku Gothic New","Hiragino Kaku Gothic ProN",sans-serif;
  color-scheme:dark;
  --t0:#7dffb230;--t1:#faff6970;--t2:#faff6900;--t3:#faff6930;--t4:#101820;--t5:#1b2836;--t6:#1f3743;--t7:#10181d;--t8:#1a1d10;--t9:#101318;--t10:#3f431f;--t11:#131a14;--t12:#2a3f52;--t13:#0e141b;--t14:#3d5a75;--t15:#171008;--t16:#5c3f24;--t17:#22402b;--t18:#4a90a8;--t19:#2a2f3a;--t20:#3a4152;--t21:#0d141a;--t22:#101713;--t23:#151823;--t24:#15170f;--t25:#16170f;--t26:#0e151b;--t27:#3a3f4a;--t28:#15171c;--t29:#4a2f43;--t30:#1a1016;--t31:#ff9dd6;--t32:#0f1216;--t33:#5c2424;--backdrop:rgba(6,8,12,.72);--shadow:rgba(0,0,0,.65);
}
[data-theme="light"]{
  color-scheme:light;
  --bg:#f3f5f8; --panel:#ffffff; --panel-2:#edf0f5;
  --line:#d4dae2; --line-soft:#e5e9ef;
  --ink:#1c232e; --muted:#465366; --dim:#6d7889;
  --yellow:#8a6d00; --cyan:#0b7ea6; --orange:#c05f0e; --green:#177a41; --red:#c94444;
  --t0:#077b3630;--t1:#8a8f0870;--t2:#8a8f0800;--t3:#8a8f0830;--t4:#e0e7ee;--t5:#cad6e3;--t6:#bed3de;--t7:#e3eaee;--t8:#eceee3;--t9:#e7eaef;--t10:#dbdebe;--t11:#e5ece6;--t12:#afc2d3;--t13:#e5eaf0;--t14:#8da7bf;--t15:#f6f0e9;--t16:#d8bea6;--t17:#c1dbc9;--t18:#5c9bb0;--t19:#c6cad4;--t20:#aeb4c4;--t21:#e6ecf1;--t22:#e8efeb;--t23:#dddfe9;--t24:#eef0e8;--t25:#eff0e8;--t26:#e5ebf0;--t27:#b6bac4;--t28:#e3e5ea;--t29:#cfb6c8;--t30:#efe5eb;--t31:#5d0538;--t32:#e9ecf0;--t33:#d8a6a6;--backdrop:rgba(25,32,44,.38);--shadow:rgba(30,42,60,.28);
}
[data-theme="light"] .btn.primary{background:#f2cf3d;border-color:#dcbb2e;color:#332f10}
[data-theme="light"] .tab.on{color:#8a6d00;border-bottom-color:#c9a400}
[data-theme="light"] .lvchip.on{background:#faf3d4}
*{margin:0;padding:0;box-sizing:border-box}
body{background:var(--bg);color:var(--ink);font-family:var(--jp);font-size:14px;line-height:1.65}
button{font-family:inherit;cursor:pointer}
code{font-family:var(--mono);font-size:.92em;color:var(--cyan);background:var(--t4);border:1px solid var(--t5);padding:1px 6px;border-radius:4px}

.app{max-width:1180px;margin:0 auto;padding:0 20px 60px}
header{padding:18px 0 10px;display:flex;flex-wrap:wrap;align-items:baseline;gap:14px}
header h1{font-size:22px;font-weight:900}
header h1 .y{color:var(--yellow)}
header .sub{color:var(--muted);font-size:13px}

.tabs{display:flex;gap:8px;border-bottom:1px solid var(--line);margin-bottom:12px;flex-wrap:wrap}
.tab{background:none;border:none;border-bottom:2px solid transparent;color:var(--muted);padding:10px 16px;font-size:14px;font-weight:700}
.tab:hover{color:var(--ink)}
.tab.on{color:var(--yellow);border-bottom-color:var(--yellow)}
.pane{display:none}
.pane.on{display:block;animation:fade .25s}
@keyframes fade{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.pane.on{animation:none}}

.hint{font-size:13px;color:var(--muted);border-left:2px solid var(--line);padding:2px 12px;margin-bottom:14px}
.hint .y{color:var(--yellow)}

/* ===== tab1: explorer ===== */
.explorer{display:grid;grid-template-columns:1fr 360px;gap:22px;align-items:start}
@media(max-width:900px){.explorer{grid-template-columns:1fr}}
.detail{position:static;margin-top:-8px}
.detail .badge{display:inline-block;font-family:var(--mono);font-size:11px;letter-spacing:.12em;text-transform:uppercase;padding:2px 10px;border-radius:99px;border:1px solid var(--line);color:var(--muted);margin-bottom:10px}
.detail h2{font-size:18px;font-weight:900;margin-bottom:8px;font-family:var(--mono)}
.detail p{font-size:13px;color:var(--muted);margin-bottom:12px}
.detail dl{font-size:13px}
.detail dt{font-family:var(--mono);color:var(--yellow);margin-top:10px;font-size:12px}
.detail dd{color:var(--muted);margin-left:0}
.detail .empty{color:var(--dim);font-size:13px;text-align:center;padding:40px 0}

/* ===== tab2: merge sim ===== */
.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px;align-items:center}
.btn{border:1px solid var(--line);background:var(--panel-2);color:var(--ink);border-radius:8px;padding:9px 16px;font-size:13px;font-weight:700;transition:all .12s}
.btn:hover{border-color:var(--muted)}
.btn.primary{background:var(--yellow);color:#111;border-color:var(--yellow)}
.btn.primary:hover{filter:brightness(1.08)}
.btn:disabled{opacity:.4;cursor:not-allowed}
select{background:var(--panel-2);color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:8px 10px;font-family:var(--mono);font-size:13px}
.msel{position:relative;display:inline-block}
.msel-btn{background:var(--panel-2);color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:8px 10px;font-family:var(--mono);font-size:13px;cursor:pointer}
.msel-pop{display:none;position:absolute;top:calc(100% + 4px);left:0;z-index:40;background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:10px 12px;flex-direction:column;gap:8px;white-space:nowrap;box-shadow:0 12px 30px var(--shadow)}
.msel.open .msel-pop{display:flex}
.msel-pop label{display:flex;gap:8px;align-items:center;cursor:pointer;font-size:13px;color:var(--ink)}
.fviz{border:1px dashed var(--line);border-radius:10px;padding:10px 12px;margin:10px 0;font-size:11.5px;color:var(--muted);font-family:var(--mono)}
.fvt{font-family:var(--jp);font-size:12.5px;color:var(--ink);margin-bottom:8px}
.fvn{font-family:var(--jp);font-size:12px;margin-top:8px;line-height:1.7}
.fvgrid{display:grid;gap:4px}
.fvgrid i{font-style:normal;text-align:center;border:1px solid var(--line);border-radius:6px;padding:4px 2px;background:var(--panel-2);line-height:1.5}
.fvgrid i.fva{border:none;background:none;color:var(--dim);padding:0}
.fvgrid i.win{border-color:var(--green);color:var(--green)}
.fvrec{display:flex;gap:8px;flex-wrap:wrap;align-items:center;border:1px solid var(--t6);border-radius:8px;padding:6px 10px;background:var(--panel-2);margin-bottom:2px}
.fvrec b{color:var(--cyan)}
.fvarr{display:flex;justify-content:space-around;color:var(--dim);font-family:var(--jp);font-size:11.5px;margin:4px 0}
.fvbar{display:flex;gap:2px;margin-top:12px}
.fvbar i{position:relative;font-style:normal;text-align:center;border:1px solid var(--line);border-radius:6px;padding:9px 2px;background:var(--panel-2)}
.fvbar i.win{border-color:var(--cyan);color:var(--cyan)}
.fvbar em.tick{position:absolute;font-style:normal;font-size:10px;color:var(--orange);top:-13px;white-space:nowrap}
body.smt-on .conn-oss{display:none}
body:not(.smt-on) .conn-smt{display:none}
.msCard{border:1px solid var(--line);border-radius:8px;padding:8px 10px;font-size:12.5px;color:var(--muted);line-height:1.7;cursor:pointer}
.msCard:hover{border-color:var(--cyan)}
.msCard .msMore{display:block;margin-top:4px;color:var(--cyan);font-size:11.5px}
.msType{flex:1;min-width:200px;border:1px dashed var(--line);border-radius:8px;padding:8px 10px;font-size:12px;color:var(--muted);line-height:1.7}
#tourPanel{position:fixed;z-index:70;background:var(--panel);border:1px solid var(--yellow);border-radius:12px;padding:12px 16px;width:min(560px,calc(100vw - 32px));box-shadow:0 18px 50px var(--shadow);display:flex;gap:12px;align-items:center;font-size:13.5px;color:var(--ink);font-family:var(--jp);line-height:1.7}
#tourPanel::before{content:'';position:absolute;top:-7px;left:26px;width:12px;height:12px;background:var(--panel);border-left:1px solid var(--yellow);border-top:1px solid var(--yellow);transform:rotate(45deg)}
#tourPanel .tourbtns{margin-left:auto;display:flex;gap:8px;flex-shrink:0}
.tourHl{outline:2px solid var(--yellow);outline-offset:3px;border-radius:8px}
.svcmap.readview .pbox{opacity:.3;border-color:var(--line)}
.svcmap.readview .pbox.qread{opacity:1;border-color:var(--cyan);box-shadow:0 0 0 1px var(--cyan) inset}
#qpipeFoldBar{display:none}
body.L8 #qpipeFoldBar{display:block;margin-bottom:12px}
body.qfold .qpipe{display:none}
body.qfold .qonly{display:none!important}
.partitions{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px}
.pcol{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:16px;min-height:180px}
.pcol h3{font-family:var(--mono);font-size:13px;color:var(--yellow);margin-bottom:12px;display:flex;justify-content:space-between}
.pcol h3 span{color:var(--dim);font-weight:400;font-size:12px}
.partbox{border:1px solid var(--t6);background:var(--t7);border-radius:8px;padding:8px 12px;margin-bottom:8px;font-family:var(--mono);font-size:13px;color:var(--cyan);display:flex;justify-content:space-between;align-items:center;transition:all .4s}
.partbox small{color:var(--dim);font-size:11px}
.partbox.new{animation:pop .4s}
@keyframes pop{from{transform:scale(.9);opacity:0}to{transform:scale(1);opacity:1}}
.partbox.inactive{opacity:.35;border-style:dashed;text-decoration:line-through}
.partbox.merged{border-color:var(--yellow);color:var(--yellow);background:var(--t8)}
.mlog{margin-top:14px;background:var(--t9);border:1px solid var(--line);border-radius:10px;padding:10px 14px;font-family:var(--mono);font-size:13px;max-height:130px;overflow-y:auto}
.mlog div{padding:3px 0;border-bottom:1px solid var(--line-soft);color:var(--muted)}
.lts{color:var(--dim);font-size:10px;margin-right:8px}
.ltag{display:inline-block;border:1px solid var(--t10);border-radius:4px;padding:0 6px;font-size:10px;color:var(--yellow);margin-right:8px;vertical-align:1px}
.mlog .y{color:var(--yellow)} .mlog .c{color:var(--cyan)} .mlog .g{color:var(--green)}

/* ===== tab3: query sim ===== */
.qgrid{display:grid;grid-template-columns:330px 1fr;gap:22px;align-items:start}
@media(max-width:900px){.qgrid{grid-template-columns:1fr}}
.controls{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:18px;position:sticky;top:16px}
.controls h3{font-size:14px;margin-bottom:4px}
.controls .sql{font-family:var(--mono);font-size:13px;background:var(--t9);border:1px solid var(--line);border-radius:8px;padding:12px;margin:12px 0;line-height:1.9;color:var(--muted)}
.sql .kw{color:var(--yellow)} .sql .off{opacity:.3;text-decoration:line-through}
.ctl{display:flex;align-items:center;gap:10px;padding:10px 0;border-top:1px solid var(--line-soft);font-size:13px}
.ctl input[type=checkbox]{accent-color:var(--yellow);width:16px;height:16px}
.ctl input[type=range]{flex:1;accent-color:var(--cyan)}
.ctl .val{font-family:var(--mono);color:var(--cyan);min-width:52px;text-align:right;font-size:13px}
.funnel{display:flex;flex-direction:column;gap:6px;margin-top:14px}
.frow{display:grid;grid-template-columns:120px 1fr 84px;gap:8px;align-items:center;font-size:12px}
.frow .fl{color:var(--muted)}
.fbar{height:14px;border-radius:4px;background:var(--line-soft);overflow:hidden}
.fbar i{display:block;height:100%;border-radius:4px;transition:width .3s}
.frow .fn{font-family:var(--mono);text-align:right;color:var(--ink)}
.f1 i{background:var(--dim)} .f2 i{background:var(--yellow)} .f3 i{background:var(--cyan)} .f4 i{background:var(--orange)} .f5 i{background:var(--green)}
.board{display:flex;flex-direction:column;gap:14px}
.qpart{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px 16px;transition:opacity .25s}
.qpart.pruned{opacity:.28}
.qpart h4{font-family:var(--mono);font-size:13px;color:var(--cyan);margin-bottom:8px;display:flex;gap:10px;align-items:baseline}
.qpart h4 em{font-style:normal;color:var(--dim);font-size:11px;font-family:var(--jp)}
.qpart h4 .tag-pruned{color:var(--red);font-size:11px;font-family:var(--jp)}
.grow{display:flex;flex-wrap:wrap;gap:5px}
.gc{width:64px;height:38px;border-radius:6px;border:1px solid var(--line);font-family:var(--mono);font-size:10px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:var(--dim);transition:all .25s;cursor:default}
.gc b{font-size:11px;font-weight:600}
.gc.read{border-color:var(--green);background:var(--t11);color:var(--green);box-shadow:0 0 6px var(--t0)}
.gc.cut-pk{border-color:var(--t12);background:var(--t13);color:var(--t14)}
.gc.cut-skip{background:var(--t15);color:var(--orange);opacity:.55;border-style:dashed;border-color:var(--t16)}
.gc.cut-part{opacity:.25}
.qlegend{display:flex;gap:14px;flex-wrap:wrap;font-size:12px;color:var(--muted);margin-top:4px}
.dot{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:5px;vertical-align:-1px}
.d-read{background:var(--t11);border:1px solid var(--green)}
.d-pk{background:var(--t13);border:1px solid var(--t12)}
.d-skip{background:var(--t15);border:1px dashed var(--t16)}
.d-part{background:var(--line-soft);border:1px solid var(--line)}
.readout{font-family:var(--mono);font-size:13px;margin-top:8px}
.readout .g{color:var(--green)} .readout .m{color:var(--muted);font-size:12px;font-family:var(--jp)}

/* ===== tab4: ORDER BY vs PRIMARY KEY ===== */
.obgrid{display:grid;grid-template-columns:320px 1fr;gap:22px;align-items:start}
@media(max-width:960px){.obgrid{grid-template-columns:1fr}}
.obpanels{display:grid;grid-template-columns:1fr 1fr;gap:16px}
@media(max-width:760px){.obpanels{grid-template-columns:1fr}}
.obcard{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:16px}
.obcard>h3{font-size:14px;margin-bottom:2px;display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.obcard .owner{font-family:var(--mono);font-size:11px;padding:2px 8px;border-radius:99px}
.owner.o-order{color:var(--green);border:1px solid var(--t17);background:var(--t11)}
.owner.o-pk{color:var(--cyan);border:1px solid var(--t6);background:var(--t7)}
.obcard .cap{font-size:13px;color:var(--muted);margin-bottom:12px}
.nochange{display:inline-block;font-size:11px;font-family:var(--jp);color:var(--green);border:1px solid var(--t17);border-radius:99px;padding:1px 8px;opacity:0;transition:opacity .2s}
.nochange.flash{opacity:1}
.dtable{width:100%;border-collapse:collapse;font-family:var(--mono);font-size:12px}
.dtable th{font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:var(--dim);padding:4px 8px;text-align:left;border-bottom:1px solid var(--line)}
.dtable td{padding:4px 8px;color:var(--muted);border-bottom:1px solid var(--line-soft)}
.dtable td.c1{color:var(--yellow)} .dtable td.c2{color:var(--ink)} .dtable td.c3{color:var(--muted)}
.dtable tr.gline td{border-top:2px solid var(--t17);position:relative}
.dtable .gtag{font-size:10px;color:var(--green);font-family:var(--jp)}
.idx-list{display:flex;flex-direction:column;gap:8px}
.idx-row{display:flex;align-items:center;gap:6px;font-family:var(--mono);font-size:12px;border:1px solid var(--t6);background:var(--t7);border-radius:8px;padding:7px 10px}
.idx-row .gref{color:var(--dim);font-size:10px;font-family:var(--jp);margin-right:4px;min-width:52px}
.kcell{padding:2px 8px;border-radius:5px;border:1px solid var(--t6);color:var(--cyan);transition:all .2s}
.kcell.off{border-style:dashed;border-color:var(--line);color:var(--dim);text-decoration:line-through;opacity:.5;background:none}
.sizebar{margin-top:12px}
.sizebar .lbl{font-size:12px;color:var(--muted);display:flex;justify-content:space-between;font-family:var(--mono)}
.sizebar .track{height:10px;border-radius:5px;background:var(--line-soft);margin-top:4px;overflow:hidden}
.sizebar .track i{display:block;height:100%;background:var(--cyan);border-radius:5px;transition:width .25s}
.ddlbox{font-family:var(--mono);font-size:13px;background:var(--t9);border:1px solid var(--line);border-radius:8px;padding:14px;line-height:2;margin:12px 0}
.ddlbox .kw{color:var(--yellow)} .ddlbox .ok{color:var(--green)} .ddlbox .pk{color:var(--cyan)} .ddlbox .cm{color:var(--dim);font-size:11px}
.pkslider{display:flex;align-items:center;gap:10px;padding:8px 0}
.pkslider input{flex:1;accent-color:var(--cyan)}
.rulebox{margin-top:14px;font-size:13px;color:var(--muted)}
.rulebox li{margin:8px 0 8px 18px}
.rulebox b{color:var(--ink)}
.qcheck{margin-top:16px}
.qc-row{display:grid;grid-template-columns:26px 1fr;gap:10px;align-items:start;border-top:1px solid var(--line-soft);padding:10px 0}
.qc-row .mark{font-size:15px;line-height:1.3}
.qc-row .sql2{font-family:var(--mono);font-size:12.5px;color:var(--ink)}
.qc-row .why{font-size:12.5px;color:var(--muted);margin-top:2px}
.qc-row.ok .mark{color:var(--green)} .qc-row.part .mark{color:var(--orange)} .qc-row.ng .mark{color:var(--red)}

.subnav{margin:0 0 18px;border-bottom:1px dashed var(--line-soft);padding-bottom:14px}
.ctxbar{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:8px 14px;margin-bottom:12px}
.ctxsum{display:flex;gap:10px;align-items:center;font-family:var(--mono);font-size:11.5px;color:var(--muted)}
.ctxq{flex:1;min-width:0;overflow-x:auto;white-space:nowrap}
.ctxbtn{margin-left:auto;background:none;border:1px solid var(--line);border-radius:6px;color:var(--muted);font-size:10.5px;padding:2px 10px;font-family:var(--jp);flex-shrink:0}
.ctxbtn:hover{color:var(--ink);border-color:var(--muted)}
.ctxfull{display:none}
.ctxbar.open .ctxfull{display:grid;grid-template-columns:1fr 1fr;gap:8px 26px;margin-top:10px;border-top:1px dashed var(--line-soft);padding-top:10px}
@media(max-width:860px){.ctxbar.open .ctxfull{grid-template-columns:1fr}}
.ctxcol{min-width:0}
.ctxbar .cl{display:block;font-family:var(--mono);font-size:10px;letter-spacing:.12em;color:var(--dim);margin-bottom:5px}
.ctxbar .cl em{font-style:normal;letter-spacing:0;text-transform:none;color:var(--dim);opacity:.8}
.ctxcode{font-family:var(--mono);font-size:11.5px;line-height:1.7;color:var(--muted);overflow-x:auto;white-space:nowrap}
.ctxcode .kw{color:var(--yellow)} .ctxcode .ok{color:var(--green)} .ctxcode .cm{color:var(--dim);font-size:10.5px}
.ctxcode .off{opacity:.35;text-decoration:line-through}
.ctxcode i{font-style:normal}
.ctxbar .q-part,.deck .q-part{color:var(--yellow)} .ctxbar .q-pk,.deck .q-pk{color:var(--cyan)} .ctxbar .q-skip,.deck .q-skip{color:var(--orange)}
.deck .cm{color:var(--dim)}

.mvrows{font-family:var(--mono);font-size:11px;color:var(--muted);line-height:1.8;margin-top:6px}
.mvrows .hl{color:var(--green)}

/* ===== 学習レベル(段階的アンロック) ===== */
.term{border-bottom:1px dashed var(--t18);cursor:help}
.term:hover{color:var(--cyan);border-bottom-color:var(--cyan)}
#mTerm .modal-box{max-width:460px}
.helpbtn{margin-left:auto;align-self:center;border:1px solid var(--line);background:var(--panel-2);color:var(--muted);border-radius:50%;width:26px;height:26px;font-weight:700;font-size:14px}
.helpbtn:hover{color:var(--ink);border-color:var(--muted)}
.lvbar{display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin-bottom:10px}
.lvbar .lvt{font-family:var(--mono);font-size:10px;letter-spacing:.12em;color:var(--dim);margin-right:2px}
