.pgpart{display:inline-block;font-family:var(--mono);font-size:11px;border:1px solid var(--t6);color:var(--cyan);border-radius:5px;padding:2px 7px;margin-right:4px}
.drow{font-family:var(--mono);font-size:12px;padding:5px 0;border-bottom:1px solid var(--line-soft);display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.drow .dwin{color:var(--yellow)}
.dcand{border:1px solid var(--line);border-radius:5px;padding:1px 7px;font-size:11px;color:var(--muted)}
.dcand.win{border-color:var(--yellow);color:var(--yellow)}
.mgr{display:flex;gap:3px;margin:4px 0 8px;max-width:520px}
.mgr i{flex:1;height:20px;border-radius:4px;background:var(--line-soft);border:1px solid var(--line);font-style:normal;font-family:var(--mono);font-size:9.5px;display:flex;align-items:center;justify-content:center;color:var(--dim)}
