.mgrcap .who{color:var(--yellow);font-family:var(--jp)}

/* ===== tabA: integrated service map ===== */
.deck{display:flex;gap:8px 0;flex-wrap:wrap;margin-bottom:14px;align-items:stretch;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:10px 4px}
