.deck-g:last-child{border-right:none}
.deck-l{flex-basis:100%;font-family:var(--mono);font-size:11.5px;letter-spacing:.12em;color:var(--muted)}
.ctl-inline{display:flex;gap:6px;align-items:center;font-size:13px;color:var(--muted);cursor:pointer;user-select:none}
