.crow{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:10px}
@media(max-width:900px){.crow{grid-template-columns:repeat(2,1fr)}}
.b-node{background:var(--panel-2);transition:all .25s}
.box.ghost{opacity:.45;border-style:dashed;position:relative}

.chipline{font-family:var(--mono);font-size:10.5px;color:var(--muted);border:1px dashed var(--line);border-radius:6px;padding:3px 8px;margin-top:6px;cursor:pointer;transition:all .2s}
.chipline:hover{border-color:var(--muted);color:var(--ink)}
.b-keeper{border-color:var(--t10);background:var(--panel-2)}
.b-keeper>.bt{color:var(--yellow)}
.b-s3{border:none;background:var(--t21);margin-top:10px}
.b-s3>.bt{color:var(--cyan)}
.b-table{border:none;background:var(--t22);margin-top:10px}
.b-table>.bt{color:var(--green)}
.b-mv{border:1px dashed var(--t17)}
.b-mv.ghostish{opacity:.4}
.prow{display:flex;gap:10px;flex-wrap:wrap;align-items:flex-start;margin-top:8px}
.b-partition{flex:1;min-width:250px;border:none;background:var(--t23)}
.b-partition>.bt{color:var(--muted);font-size:11.5px}
.zone{font-family:var(--mono);font-size:11px;letter-spacing:.12em;color:var(--muted);margin:6px 0 2px}
.conn{text-align:center;font-size:12px;color:var(--muted);border-top:1px dashed var(--line-soft);border-bottom:1px dashed var(--line-soft);padding:4px 0;margin:10px 0 2px}
.bhead{display:flex;gap:8px;align-items:flex-start;margin-bottom:4px}
.bico{font-size:15px;line-height:1.3}
.bhead .bt{display:block}
.brole{display:block;font-size:12.5px;color:var(--muted);font-family:var(--jp);margin-top:2px;cursor:default}
.pbox{border:1px solid var(--t6);background:var(--t7);border-radius:8px;padding:7px 10px;margin-top:8px;font-family:var(--mono);font-size:12px;color:var(--cyan);cursor:pointer;transition:all .3s}
.pbox .pexp{color:var(--dim);margin-right:6px;font-size:11px}
.pbox .pico{margin-right:6px}
.pbox .prows{color:var(--muted);font-size:12px}
.pbox .plvl{border:1px solid var(--line);border-radius:4px;padding:0 5px;color:var(--dim);font-size:10px;margin-left:6px}
