.pbox .pname{color:var(--ink);font-weight:600;font-size:12px;margin-right:2px}
.pbox:hover{border-color:var(--muted)}
.pbox .pmeta{color:var(--dim);font-size:10.5px}
.pbox.new{animation:pop .4s}
.pbox.inactive{opacity:.35;border-style:dashed;text-decoration:line-through}
.pbox.merged{border-color:var(--yellow);color:var(--yellow);background:var(--t8)}
.pbox.rewrote{border-color:var(--red)}
