.fch{border:1px solid var(--line);background:var(--panel-2);border-radius:6px;padding:3px 8px;font-family:var(--mono);font-size:11px;color:var(--muted);cursor:pointer;transition:all .15s}
.fch:hover{border-color:var(--yellow);color:var(--yellow)}
.gstrip{display:flex;gap:3px;flex-basis:100%;cursor:pointer}
.gstrip:hover i{border-color:var(--yellow);color:var(--yellow)}
.gstrip i{flex:1;height:16px;background:var(--t11);border:1px solid var(--t17);border-radius:3px;font-style:normal;font-family:var(--mono);font-size:9px;color:var(--green);display:flex;align-items:center;justify-content:center}
