.arow .albl{font-size:13px;color:var(--muted);text-align:right}
@media(max-width:700px){.arow .albl{text-align:left}}
.arow .albl b{display:block;font-family:var(--mono);font-size:13px;color:var(--ink)}
.abar{display:flex;height:36px;border-radius:8px;overflow:hidden;border:1px solid var(--line)}
.acell{display:flex;align-items:center;justify-content:center;font-family:var(--mono);font-size:11px;border-right:1px solid var(--bg)}
.acell:last-child{border-right:none}
.acell.ag{background:var(--t11);color:var(--green)}
.acell.ac{background:var(--t7);color:var(--cyan)}
.acell.ab{background:var(--t8);color:var(--yellow)}
.flowrow{display:flex;gap:6px;align-items:stretch;flex-wrap:wrap;margin-bottom:18px}
.fstage{flex:1;min-width:130px;border:1px solid var(--line);background:var(--panel-2);border-radius:8px;padding:10px 12px}
.fstage b{font-family:var(--mono);font-size:12px;display:block}
.fstage span{font-size:11.5px;color:var(--muted)}
.fstage.st-mem b{color:var(--cyan)} .fstage.st-disk b{color:var(--green)} .fstage.st-proc b{color:var(--yellow)}
.farrow{align-self:center;color:var(--dim);font-size:14px}

/* ===== glow(操作アニメーション) ===== */
.glow{border-color:var(--yellow)!important;box-shadow:0 0 0 1px var(--yellow),0 0 18px var(--t3);opacity:1!important}

/* ===== tab7: update/delete sim ===== */
.udboard{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px;margin:16px 0}
.udpart{border:1px solid var(--t6);background:var(--t7);border-radius:10px;padding:10px 12px;font-family:var(--mono);font-size:12px;color:var(--cyan);transition:all .4s}
.udpart .pn{display:flex;justify-content:space-between;margin-bottom:6px}
.udpart .pn em{font-style:normal;color:var(--dim);font-size:10px;font-family:var(--jp)}
.udpart.gone{opacity:0;transform:scale(.85)}
.udpart.rewrote{border-color:var(--red)}
.udpart.patch{border-color:var(--t10);color:var(--yellow);border-style:dashed}
.udpart .maskbadge{display:inline-block;font-size:10px;color:var(--orange);border:1px dashed var(--t16);border-radius:4px;padding:0 6px;margin-top:6px}
.rchip{display:inline-block;padding:2px 7px;margin:2px;border-radius:5px;background:var(--t32);border:1px solid var(--line);color:var(--muted);font-size:11.5px;transition:all .3s}
.rchip.tgt{border-color:var(--yellow);color:var(--yellow)}
.rchip.dead{text-decoration:line-through;color:var(--red);border-color:var(--t33);opacity:.6}
.rchip.upd{color:var(--green);border-color:var(--t17)}
.rchip.v2{color:var(--green);border-color:var(--t17)}
.udverdict{border:1px solid var(--line);border-left:3px solid var(--yellow);background:var(--panel);border-radius:10px;padding:14px 18px;font-size:13px;color:var(--muted)}
.udverdict b{color:var(--ink)}
.udverdict .cost{display:inline-flex;gap:3px;margin-left:8px;vertical-align:middle}
.udverdict .cost i{width:14px;height:8px;border-radius:2px;background:var(--line)}
.udverdict .cost i.on{background:var(--orange)}
.udmeta{font-family:var(--mono);font-size:12px;color:var(--dim);margin-top:6px}

/* ===== tab8: doc map ===== */
.refsec{margin-bottom:26px}
.refsec>h3{font-size:15px;margin-bottom:4px}
.refsec .rs-sub{font-size:13px;color:var(--muted);margin-bottom:12px}
.refgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:10px}
.refcard{display:block;border:1px solid var(--line);background:var(--panel);border-radius:10px;padding:12px 14px;text-decoration:none;transition:all .12s}
.refcard:hover{border-color:var(--yellow);transform:translateY(-1px)}
.refcard b{font-size:13px;color:var(--ink);display:block}
.refcard span{font-size:12.5px;color:var(--muted);line-height:1.5;display:block;margin-top:3px}
.refcard .tabref{display:inline-block;font-size:10px;font-family:var(--mono);color:var(--green);border:1px solid var(--t17);border-radius:99px;padding:0 7px;margin-top:6px}
